functions.getGridWidth:
function getGridWidth() {
		try {
			var w = window.parent.$("#screensWrapper").width();
			if(w>100)
				return window.parent.$("#screensWrapper").width()-10;
			else
				return $(window).width()-10;
		} catch (e) {
			console.log(e.message);
			return $(window).width()-10;
		}
	}

functions.shortcutKey:
function shortcutKey(){ 		
    	$(document).bind('keydown', function(e) {
    		var keyCode = (e.keyCode) ? e.keyCode : ((e.charCode) ? e.charCode : e.which);
    		if (e.originalEvent.altKey) {
    			// ALT + S     Search                   
    			if (keyCode === 83) {
    				reloadSearchGrid();
    				e.preventDefault();
    				return false;

    			}
    			// ALT + N      Reset                 
    			if (keyCode == 78) {
    				resetAll();
    				e.preventDefault();
    				return false;
    			}
    			// ALT + F    Add New
    			if (keyCode == 70){
    				addnew();
    				e.preventDefault();
    				return false;
    			}

    		}
    	});
    }

functions.doExport:
function doExport() {
		if ($("#fromLogDate").val() == "") {
			window.parent.showAlert('Please fill all mandatory fields');
			$("#fromLogDate").focus();
			event.preventDefault();
			return false;
		}
		if ($("#toLogDate").val() == "") {
			window.parent.showAlert('Please fill all mandatory fields');
			$("#toLogDate").focus();
			event.preventDefault();
			return false;
		}
		if ($("#log").val() == "-1") {
			window.parent.showAlert('Please fill all mandatory fields');
			$("#log").focus();
			event.preventDefault();
			return false;
		}
		var date = new Date();
		var curr_date = date.getDate();
		var curr_month = date.getMonth();
		curr_month = curr_month + 1;
		var curr_year = date.getFullYear();
		var today_date = new Date(curr_year + '/' + curr_month + '/'
				+ curr_date);
		var startdatevalue = $("#fromLogDate").val();
		var enddatevalue = $("#toLogDate").val();
		var log = $("#log").val();
		var inputDate = startdatevalue.split('/');
		var startdate = new Date(inputDate[2] + '/' + inputDate[1] + '/'
				+ inputDate[0]);
		var inputDate2 = enddatevalue.split('/');
		var enddate = new Date(inputDate2[2] + '/' + inputDate2[1] + '/'
				+ inputDate2[0]);
		if (inputDate2[2] > inputDate[2]) {
			if (inputDate2[1] > inputDate[1]) {
				alert("Date Range Should Be an Year ");
				return false;
			}
			if (inputDate2[1] == inputDate[1])
				if (inputDate2[0] > inputDate[0]) {
					alert("Date Range Should Be an Year ");
					return false;
				}

		}
		if (startdate > enddate) {
			window.parent.showAlert('From date should be greater than To date');
			$("#toLogDate").focus();
			return false;
		} else if (startdate > today_date) {
			window.parent.showAlert('From date should be greater than today');
			$("#fromLogDate").focus();
			return false;
		} else if (enddate > today_date) {
			window.parent.showAlert('To date should be greater than today');
			$("#toLogDate").focus();
			return false;
		}
		var fromLogDate = $("#fromLogDate").val();
		var toLogDate = $("#toLogDate").val();

		var retVal = $.ajax({
			type: "POST",
            url: "generateUserAuditLogExport",
            data : {
            	fromDate : fromLogDate,
            	toDate : toLogDate,
            	logType : log
    		},
            success: function(data) {
                if(data.jsonMessage == null) {
            	    window.parent.pendingReportSearch('?uuId='+data.reportId);
                } else {
            	    window.parent.showAlert(data.jsonMessage);
            	    window.parent.pendingReportSearch();
                }
            }
		});
	}
